65	  page_title: string | null;
66	  page_type: PageType;
67	  status: ScanStatus;
68	  overall_score: number | null;
69	  issues_found: number;
70	  critical_issues: number;
71	  warnings: number;
72	  quick_wins: number;
73	  screenshot_url: string | null;
74	  device: "desktop" | "mobile" | "both";
75	  share_token: string | null;
76	  is_public: boolean;
77	  team_id: string | null;
78	  created_at: string;
79	  completed_at: string | null;
