81	
82	export type IndustryType = "saas" | "ecommerce" | "agency" | "finance" | "healthcare";
83	
84	export interface IndustryBenchmark {
85	  id: string;
86	  industry: string;
87	  page_type: string;
88	  pillar: string;
89	  avg_score: number;
90	  sample_size: number;
