94	// ── CRO Pillars ──────────────────────────────────────────────
95	
96	export type CroPillar =
97	  | "value_proposition"
98	  | "cta_effectiveness"
99	  | "trust_signals"
100	  | "visual_hierarchy"
101	  | "mobile_experience"
102	  | "content_copy"
103	  | "page_performance";
