105	export type Severity = "critical" | "warning" | "info" | "passed";
106	export type Effort = "quick" | "moderate" | "significant";
107	
108	export interface Finding {
109	  id: string;
110	  title: string;
111	  severity: Severity;
112	  current_state: string;
113	  recommendation: string;
114	  ai_suggestion: string;
115	  is_premium: boolean;
116	  effort: Effort;
117	  estimated_lift: string; // e.g. "1-3% conversion lift"
118	  category: string; // e.g. "Copy", "Design", "Technical"
119	}
120	
121	export interface PillarResult {
122	  id: string;
123	  scan_id: string;
124	  pillar: CroPillar;
125	  score: number;
126	  weight: number; // pillar weight in overall score (0-1)
127	  benchmark: number; // industry average for this pillar
128	  findings: Finding[];
129	}
