import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import type { AppNotification } from "@/types";

const NOTIFICATIONS_KEY = "notifications";

// ── useNotifications ──────────────────────────────────────────────
// Fetches last 20 notifications for the current user, newest first.

export function useNotifications() {
  const { user } = useAuth();

  return useQuery<AppNotification[]>({
    queryKey: [NOTIFICATIONS_KEY, user?.id],
    enabled: !!user?.id,
    queryFn: async () => {
      const { data, error } = await supabase
        .from("notifications")
        .select("*")
        .eq("user_id", user!.id)
        .order("created_at", { ascending: false })
        .limit(20);

      if (error) throw error;
      return (data ?? []) as AppNotification[];
    },
    staleTime: 30_000,
  });
}

// ── useUnreadCount ────────────────────────────────────────────────
// Returns the count of unread notifications (read_at IS NULL).

export function useUnreadCount(): number {
  const { data } = useNotifications();
  if (!data) return 0;
  return data.filter((n) => n.read_at === null).length;
}

// ── useMarkRead ───────────────────────────────────────────────────
// Sets read_at = NOW() for a single notification.

export function useMarkRead() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (notificationId: string) => {
      const { error } = await supabase
        .from("notifications")
        .update({ read_at: new Date().toISOString() })
        .eq("id", notificationId)
        .eq("user_id", user!.id);

      if (error) throw error;
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: [NOTIFICATIONS_KEY, user?.id] });
    },
  });
}

// ── useMarkAllRead ────────────────────────────────────────────────
// Marks all unread notifications as read for the current user.

export function useMarkAllRead() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async () => {
      const { error } = await supabase
        .from("notifications")
        .update({ read_at: new Date().toISOString() })
        .eq("user_id", user!.id)
        .is("read_at", null);

      if (error) throw error;
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: [NOTIFICATIONS_KEY, user?.id] });
    },
  });
}

// ── useDismissNotification ────────────────────────────────────────
// Permanently deletes a notification for the current user.

export function useDismissNotification() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase
        .from("notifications")
        .delete()
        .eq("id", id)
        .eq("user_id", user!.id);

      if (error) throw error;
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: [NOTIFICATIONS_KEY, user?.id] });
    },
  });
}

