import { useNavigate } from "react-router-dom";
import { motion } from "framer-motion";
import {
  ScanLine,
  TrendingUp,
  TrendingDown,
  Users,
  Info,
} from "lucide-react";
import { cn } from "@/lib/utils";
import type { AppNotification, NotificationType } from "@/types";

// ── Time formatting ───────────────────────────────────────────────

function timeAgo(isoString: string): string {
  const diffMs = Date.now() - new Date(isoString).getTime();
  const diffSec = Math.floor(diffMs / 1000);
  if (diffSec < 60) return `${diffSec}s ago`;
  const diffMin = Math.floor(diffSec / 60);
  if (diffMin < 60) return `${diffMin}m ago`;
  const diffHr = Math.floor(diffMin / 60);
  if (diffHr < 24) return `${diffHr}h ago`;
  const diffDay = Math.floor(diffHr / 24);
  return `${diffDay}d ago`;
}

// ── Icon mapping ──────────────────────────────────────────────────

const TYPE_ICON: Record<NotificationType, React.ElementType> = {
  scan_complete: ScanLine,
  score_improved: TrendingUp,
  score_dropped: TrendingDown,
  team_invite: Users,
  finding_reappeared: Info,
  system: Info,
  // compat with legacy types stored in DB
  score_drop: TrendingDown,
  weekly_digest: Info,
  referral_reward: Users,
};

const TYPE_COLOR: Record<NotificationType, string> = {
  scan_complete: "text-primary bg-primary/10",
  score_improved: "text-emerald-600 bg-emerald-50",
  score_dropped: "text-destructive bg-destructive/10",
  team_invite: "text-violet-600 bg-violet-50",
  finding_reappeared: "text-amber-600 bg-amber-50",
  system: "text-muted-foreground bg-muted/60",
  score_drop: "text-destructive bg-destructive/10",
  weekly_digest: "text-muted-foreground bg-muted/60",
  referral_reward: "text-emerald-600 bg-emerald-50",
};

// ── Component ─────────────────────────────────────────────────────

interface NotificationItemProps {
  notification: AppNotification;
  onMarkRead: (id: string) => void;
}

export function NotificationItem({ notification, onMarkRead }: NotificationItemProps) {
  const navigate = useNavigate();
  const isUnread = notification.read_at === null;
  const Icon = TYPE_ICON[notification.type] ?? Info;
  const colorClass = TYPE_COLOR[notification.type] ?? TYPE_COLOR.system;

  const handleClick = () => {
    if (isUnread) {
      onMarkRead(notification.id);
    }
    if (notification.link) {
      navigate(notification.link);
    }
  };

  return (
    <motion.button
      type="button"
      onClick={handleClick}
      className={cn(
        "w-full flex items-start gap-3 px-4 py-3 text-left transition-colors",
        "hover:bg-muted/50 focus-visible:outline-none focus-visible:bg-muted/50",
        isUnread && "bg-primary/[0.03]",
      )}
      initial={{ opacity: 0, y: -4 }}
      animate={{ opacity: 1, y: 0 }}
    >
      {/* Icon */}
      <div className={cn("mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg", colorClass)}>
        <Icon className="h-3.5 w-3.5" />
      </div>

      {/* Content */}
      <div className="flex-1 min-w-0">
        <p className={cn("text-sm leading-tight truncate", isUnread ? "font-semibold text-foreground" : "font-medium text-foreground/80")}>
          {notification.title}
        </p>
        {notification.body && (
          <p className="mt-0.5 text-xs text-muted-foreground line-clamp-2 leading-relaxed">
            {notification.body}
          </p>
        )}
        <p className="mt-1 text-xs text-muted-foreground/60">{timeAgo(notification.created_at)}</p>
      </div>

      {/* Unread dot */}
      {isUnread && (
        <span className="mt-1.5 h-2 w-2 shrink-0 rounded-full bg-primary" aria-label="Unread" />
      )}
    </motion.button>
  );
}

import { useState } from "react";
import { Bell } from "lucide-react";
import { AnimatePresence, motion } from "framer-motion";
import { Button } from "@/components/ui/button";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";
import { useNotifications, useUnreadCount, useMarkRead, useMarkAllRead } from "@/hooks/use-notifications";
import { NotificationItem } from "./NotificationItem";

export function NotificationBell() {
  const [open, setOpen] = useState(false);
  const { data: notifications, isLoading } = useNotifications();
  const unreadCount = useUnreadCount();
  const { mutate: markRead } = useMarkRead();
  const { mutate: markAllRead, isPending: isMarkingAll } = useMarkAllRead();

  const handleMarkRead = (id: string) => {
    markRead(id);
  };

  const handleMarkAll = () => {
    markAllRead();
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="ghost"
          size="sm"
          className="relative h-8 w-8 p-0 text-muted-foreground hover:text-foreground"
          aria-label={unreadCount > 0 ? `${unreadCount} unread notifications` : "Notifications"}
        >
          <Bell className="h-4 w-4" />
          {unreadCount > 0 && (
            <span
              className={cn(
                "absolute -top-0.5 -right-0.5 flex h-4 min-w-[1rem] items-center justify-center",
                "rounded-full bg-primary px-1 text-[10px] font-semibold leading-none text-primary-foreground",
              )}
              aria-hidden="true"
            >
              {unreadCount > 99 ? "99+" : unreadCount}
            </span>
          )}
        </Button>
      </PopoverTrigger>

      <PopoverContent
        align="end"
        sideOffset={8}
        className="w-[min(380px,calc(100vw-2rem))] p-0 shadow-lg"
      >
        {/* Header */}
        <div className="flex items-center justify-between border-b border-border/50 px-4 py-3">
          <p className="text-sm font-semibold text-foreground">Notifications</p>
          {unreadCount > 0 && (
            <button
              type="button"
              onClick={handleMarkAll}
              disabled={isMarkingAll}
              className="text-xs text-primary hover:text-primary/80 transition-colors disabled:opacity-50"
            >
              Mark all read
            </button>
          )}
        </div>

        {/* List */}
        <div className="max-h-[400px] overflow-y-auto overscroll-contain">
          {isLoading ? (
            <div className="flex flex-col gap-0">
              {[1, 2, 3].map((i) => (
                <div key={i} className="flex items-start gap-3 px-4 py-3">
                  <div className="h-8 w-8 shrink-0 rounded-lg bg-muted animate-pulse" />
                  <div className="flex-1 space-y-1.5">
                    <div className="h-3.5 w-3/4 rounded bg-muted animate-pulse" />
                    <div className="h-3 w-1/2 rounded bg-muted animate-pulse" />
                  </div>
                </div>
              ))}
            </div>
          ) : !notifications || notifications.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-10 gap-2">
              <div className="flex h-10 w-10 items-center justify-center rounded-full bg-muted/50">
                <Bell className="h-4 w-4 text-muted-foreground/50" />
              </div>
              <p className="text-sm font-medium text-foreground">No notifications yet</p>
              <p className="text-xs text-muted-foreground text-center max-w-[180px]">
                Scan completions and score alerts will appear here
              </p>
            </div>
          ) : (
            <AnimatePresence initial={false}>
              {notifications.map((notification, index) => (
                <motion.div
                  key={notification.id}
                  initial={{ opacity: 0, y: -6 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, height: 0, overflow: "hidden" }}
                  transition={{ delay: index * 0.04, duration: 0.18 }}
                >
                  <NotificationItem
                    notification={notification}
                    onMarkRead={(id) => {
                      handleMarkRead(id);
                      if (notification.link) setOpen(false);
                    }}
                  />
                  {index < notifications.length - 1 && (
                    <div className="mx-4 h-px bg-border/30" />
                  )}
                </motion.div>
              ))}
            </AnimatePresence>
          )}
        </div>

        {/* Footer */}
        {notifications && notifications.length > 0 && (
          <div className="border-t border-border/50 px-4 py-2.5">
            <p className="text-xs text-muted-foreground">
              Showing last {notifications.length} notification{notifications.length !== 1 ? "s" : ""}
            </p>
          </div>
        )}
      </PopoverContent>
    </Popover>
  );
}

