// ── 13. Dispatch webhooks (fire-and-forget) ────────────────────
try {
  fetch(`${Deno.env.get("SUPABASE_URL")}/functions/v1/webhook-dispatch`, {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      user_id: user.id,
      event: "scan.completed",
      payload: {
        scan_id: scanId,
        url,
        overall_score: scoring.overall_score,
        issues_found: scoring.issues_found,
        critical_issues: scoring.critical_issues,
        completed_at: new Date().toISOString(),
      },
    }),
  }).catch((err: unknown) => console.warn("Webhook dispatch failed (non-fatal):", err));
} catch (webhookErr) {
  console.warn("Webhook dispatch error (non-fatal):", webhookErr);
}

// ── 14. In-app notifications (non-fatal) ──────────────────────
try {
  // Always insert scan_complete notification
  await supabase.from("notifications").insert({
    user_id: user.id,
    type: "scan_complete",
    title: "Scan Complete",
    body: `Your audit of ${url} scored ${scoring.overall_score}/100`,
    link: `/reports/${scanId}`,
  });

  // Compare with previous scan for same URL to detect score changes
  const { data: previousHistory } = await supabase
    .from("scan_history")
    .select("score, scan_id")
    .eq("user_id", user.id)
    .eq("url_hash", url.toLowerCase().trim())
    .neq("scan_id", scanId)
    .order("scanned_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  if (previousHistory) {
    const delta = scoring.overall_score - previousHistory.score;
    if (delta >= 5) {
      await supabase.from("notifications").insert({
        user_id: user.id,
        type: "score_improved",
        title: "Score Improved!",
        body: `${url} went from ${previousHistory.score} to ${scoring.overall_score}`,
        link: `/reports/${scanId}`,
      });
    } else if (delta <= -5) {
      await supabase.from("notifications").insert({
        user_id: user.id,
        type: "score_dropped",
        title: "Score Dropped",
        body: `${url} went from ${previousHistory.score} to ${scoring.overall_score}`,
        link: `/reports/${scanId}`,
      });
    }
  }
} catch (notifErr) {
  // Non-fatal: notifications must never fail the scan
  console.warn("Notification insert failed (non-fatal):", notifErr);
}

return corsResponse({ scan_id: scanId, overall_score: scoring.overall_score });
